  if(st.chainsSpec&&Object.keys(st.chainsSpec).length===0)S.chains=D.defaultChains();
  for(let i=2;i<=16;i++){const k='e'+i+'.';if(S.p[k+'mode']===3){S.p[k+'mode']=2;S.p[k+'lsh']=D.RSHAPE[S.p[k+'rsh']|0];}} // v1.9.5: Random type is now an LFO shape
  S.tabs=Object.assign({a:'Sine to Saw',b:'Sine to Saw',c:'Sine to Saw',d:'Sine to Saw',e:'Sine to Saw',f:'Sine to Saw'},st.tabs||{});if(!st.fact&&(st.v||0)<4)for(let i=1;i<=16;i++){const k='e'+i+'.sync';if(!(st.p&&k in st.p))S.p[k]=0;} // saves before v1.9.1 used the Length knob for drawn envelopes
  if(!st.fact&&(st.v||0)<5)for(const o of 'abcdef'){const k=o+'.us',v=S.p[k];if(v>=2&&v<=5)S.p[k]=v===5?2:v+1;} // v1.9.3 put JP Super right after Supersaw in the list
  if(!st.fact&&(st.v||0)<3&&st.tabs)for(const o in S.tabs)if(st.tabs[o]==='Sine to Saw')S.tabs[o]='Soft to Buzz'; // saves before v1.7.7: keep their old table sound
  S.frames={};tableCache.a=tableCache.b=tableCache.c=tableCache.d=tableCache.e=tableCache.f=null;
  if(st.seq)S.seq=JSON.parse(JSON.stringify(st.seq));S.envpts=st.envpts?JSON.parse(JSON.stringify(st.envpts)):{};if(st.draw)S.draw=JSON.parse(JSON.stringify(st.draw));for(let i=0;i<16;i++){const d=S.draw[i];if(!d||!d.length||!d.some(v=>v)){S.draw[i]=[];for(let k=0;k<32;k++)S.draw[i].push(i===3?k/31:Math.exp(-k/8));}}if(st.custom)S.custom=JSON.parse(JSON.stringify(st.custom));while(S.custom.length<20){const a=[];for(let q=0;q<32;q++)a.push(Math.sin(q/32*Math.PI*2));S.custom.push(a);}
  S.mnames=[1,2,3,4,5,6,7,8].map(i=>(st.mnames&&st.mnames[i-1])||'Macro '+i);(window.MTILES||[]).forEach(t=>t._upd&&t._upd());
