/* keyboard */
const LOW=36,HIGH=96;const downKeys=new Set();const keyEls={};
function isBlack(n){return [1,3,6,8,10].includes(n%12);}
function buildKeys(kb){let whites=0;for(let n=LOW;n<=HIGH;n++)if(!isBlack(n))whites++;const ww=100/whites;let wi=0;
  for(let n=LOW;n<=HIGH;n++){if(!isBlack(n)){const el=h('div',{class:'wk',style:'left:'+wi*ww+'%;width:'+ww+'%'});el.dataset.n=n;if(n%12===0)el.appendChild(h('span',{style:'position:absolute;bottom:2px;left:3px;font-size:9px;color:#333',text:'C'+(n/12-1)}));kb.appendChild(el);keyEls[n]=el;wi++;}}
  wi=0;for(let n=LOW;n<=HIGH;n++){if(isBlack(n)){const el=h('div',{class:'bk',style:'left:'+(wi*ww-ww*.3)+'%;width:'+ww*.6+'%'});el.dataset.n=n;kb.appendChild(el);keyEls[n]=el;}else wi++;}
  const act={};kb.addEventListener('pointerdown',e=>{const t=e.target.closest('[data-n]');if(!t)return;kb.setPointerCapture(e.pointerId);const n=+t.dataset.n;const r=t.getBoundingClientRect();const vel=clamp(.35+(e.clientY-r.top)/r.height*.65,.2,1);act[e.pointerId]=n;press(n,vel);});
  kb.addEventListener('pointermove',e=>{if(act[e.pointerId]===undefined)return;const t=document.elementFromPoint(e.clientX,e.clientY),k=t&&t.closest&&t.closest('[data-n]');if(k&&+k.dataset.n!==act[e.pointerId]){release(act[e.pointerId]);act[e.pointerId]=+k.dataset.n;press(+k.dataset.n,.7);}});
  const up=e=>{if(act[e.pointerId]!==undefined){release(act[e.pointerId]);delete act[e.pointerId];}};kb.addEventListener('pointerup',up);kb.addEventListener('pointercancel',up);}
function press(n,v){if(downKeys.has(n))return;downKeys.add(n);keyEls[n]&&keyEls[n].classList.add('dn');noteOn(n,v||.8);}
function release(n){if(!downKeys.has(n))return;downKeys.delete(n);keyEls[n]&&keyEls[n].classList.remove('dn');noteOff(n);}
/* Ableton style computer keyboard: A row = white keys, W row = black keys, Z/X octave, C/V velocity */
const QW={KeyA:0,KeyW:1,KeyS:2,KeyE:3,KeyD:4,KeyF:5,KeyT:6,KeyG:7,KeyY:8,KeyH:9,KeyU:10,KeyJ:11,KeyK:12,KeyO:13,KeyL:14,KeyP:15,Semicolon:16,Quote:17};
let qOct=4,qVel=.8;const qDown={};
const noteName=n=>['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'][n%12]+(Math.floor(n/12)-1);
addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey)return;const t=e.target;if(t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT'))return;
  const c=e.code;
  if(c==='KeyZ'){qOct=Math.max(0,qOct-1);toast('Keys start at '+noteName(qOct*12+12));return;}
  if(c==='KeyX'){qOct=Math.min(8,qOct+1);toast('Keys start at '+noteName(qOct*12+12));return;}
  if(c==='KeyC'){qVel=Math.max(.1,qVel-.15);toast('Key velocity '+Math.round(qVel*127));return;}
  if(c==='KeyV'){qVel=Math.min(1,qVel+.15);toast('Key velocity '+Math.round(qVel*127));return;}
  if(QW[c]===undefined)return;const n=clamp(qOct*12+12+QW[c],0,127);qDown[c]=n;press(n,qVel);e.preventDefault();});
addEventListener('keyup',e=>{const k=e.code;if(qDown[k]!==undefined){release(qDown[k]);delete qDown[k];}});
